mapper.select:
WITH VER AS (
) SELECT /* ci.sc.cm.at.ApiTestMapper.select.selectProdApiTestList - API 테스트 목록 조회 */ PRDCT.SAAS_PRDCT_ID /* SAAS제품아이디 */ , PRDCT.SAAS_PRDCT_NM /* SAAS제품명 */ , RSLT.API_VER_SN /* API버전일련번호 */ , RSLT.SRVR_SE_CD /* 서버구분코드 */ , (CASE WHEN RSLT.SRVR_SE_CD IS NULL THEN RSLT.SRVR_SE_CD ELSE USCM.SF_COMM_CD_NM(RSLT.SRVR_SE_CD) END) AS SRVR_SE_NM /* 서버구분코드명 */ , PRDCT.GDS_GDNTC_REG_YN /* 상품안내문등록여부 */ , COALESCE(MAX(RSLT.CMNC_DT), null) AS CMNC_DT /* 통신일시(최댓값) */ , ( SELECT LATEST_VER FROM VER ) AS API_LATEST_VER /* API 최신 버전 */ , COALESCE(CM.API_CMNC_SCS_YN, 'N') AS API_CMNC_SCS_YN /* API통신성공여부 */ , PRDCT.SAAS_PRDCT_API_VER_SN /* SAAS제품API버전일련번호 */ FROM USCM.TBCM_SAAS_PRDCT_M PRDCT LEFT OUTER JOIN USCM.TBCM_PRDCT_API_CMNCRSLT_L RSLT ON PRDCT.SAAS_PRDCT_ID = RSLT.SAAS_PRDCT_ID AND RSLT.SRVR_SE_CD = 'A0060002' LEFT OUTER JOIN USCM.TBCM_CMNC_MNG_L CM ON RSLT.SAAS_PRDCT_ID = CM.SAAS_PRDCT_ID AND RSLT.SRVR_SE_CD = CM.SRVR_SE_CD WHERE 1 = 1 AND PRDCT.USE_YN = 'Y'
AND PRDCT.SAAS_PRDCT_NM ILIKE CONCAT('%', #{saasPrdctNm}, '%')
AND (CASE WHEN RSLT.API_VER_SN IS NULL THEN ( SELECT LATEST_VER FROM VER ) ELSE RSLT.API_VER_SN END) = #{apiVerSn}
AND PRDCT.GDS_GDNTC_REG_YN = #{gdsGdntcRegYn} AND RSLT.API_VER_SN = PRDCT.SAAS_PRDCT_API_VER_SN
AND (CASE WHEN RSLT.API_VER_SN = ( SELECT LATEST_VER FROM VER ) THEN COALESCE(CM.API_CMNC_SCS_YN, 'N') ELSE 'Y' END) = #{apiCmncScsYn}
GROUP BY PRDCT.SAAS_PRDCT_ID, PRDCT.SAAS_PRDCT_NM, RSLT.API_VER_SN, RSLT.SRVR_SE_CD, PRDCT.GDS_GDNTC_REG_YN, CM.API_CMNC_SCS_YN, PRDCT.SAAS_PRDCT_API_VER_SN ORDER BY PRDCT.SAAS_PRDCT_NM, RSLT.API_VER_SN DESC
LIMIT #{pageSize} OFFSET (#{currentPage} - 1) * #{pageSize}

SELECT /* ci.sc.cm.at.ApiTestMapper.select.selectApiTestTot - API 테스트 목록 수 조회 */ COUNT(1) FROM ( WITH VER AS (
) SELECT PRDCT.SAAS_PRDCT_ID , RSLT.SRVR_SE_CD , RSLT.API_VER_SN FROM USCM.TBCM_SAAS_PRDCT_M PRDCT LEFT OUTER JOIN USCM.TBCM_PRDCT_API_CMNCRSLT_L RSLT ON PRDCT.SAAS_PRDCT_ID = RSLT.SAAS_PRDCT_ID AND RSLT.SRVR_SE_CD = 'A0060002' LEFT OUTER JOIN USCM.TBCM_CMNC_MNG_L CM ON RSLT.SAAS_PRDCT_ID = CM.SAAS_PRDCT_ID AND RSLT.SRVR_SE_CD = CM.SRVR_SE_CD WHERE 1 = 1 AND PRDCT.USE_YN = 'Y'
AND PRDCT.SAAS_PRDCT_NM ILIKE CONCAT('%', #{saasPrdctNm}, '%')
AND (CASE WHEN RSLT.API_VER_SN IS NULL THEN ( SELECT LATEST_VER FROM VER ) ELSE RSLT.API_VER_SN ) = #{apiVerSn}
AND PRDCT.GDS_GDNTC_REG_YN = #{gdsGdntcRegYn} AND RSLT.API_VER_SN = PRDCT.SAAS_PRDCT_API_VER_SN
AND (CASE WHEN RSLT.API_VER_SN = ( SELECT LATEST_VER FROM VER ) THEN COALESCE(CM.API_CMNC_SCS_YN, 'N') ELSE 'Y' END) = #{apiCmncScsYn}
GROUP BY PRDCT.SAAS_PRDCT_ID, RSLT.SRVR_SE_CD, RSLT.API_VER_SN )

SELECT /* ci.sc.cm.at.ApiTestMapper.select.selectProdApiTestInfo - 등록 테스트 상품 정보 */ DISTINCT PRDCT.SAAS_PRDCT_PVSN_MTH_SE_CD /* SAAS제품제공방식구분코드 */ , USCM.SF_COMM_CD_NM(PRDCT.SAAS_PRDCT_PVSN_MTH_SE_CD) AS SAAS_PRDCT_PVSN_MTH_SE_NM /* SAAS제품제공방식구분코드명 */ , PRDCT.SAAS_PRDCT_ID /* SAAS제품아이디 */ , PRDCT.SAAS_PRDCT_NM /* SAAS제품명 */ , PRDCT.SAAS_PRDCT_MKR_CD /* SAAS제품제조사코드 */ , USCM.SF_COMM_CD_NM(PRDCT.SAAS_PRDCT_MKR_CD) AS SAAS_PRDCT_MKR_NM /* SAAS제품제조사코드명 */ , PRDCT.SAAS_PRDCT_TYPE_CD /* SAAS제품유형코드 */ , USCM.SF_COMM_CD_NM(PRDCT.SAAS_PRDCT_TYPE_CD) AS SAAS_PRDCT_TYPE_NM /* SAAS제품유형코드명*/ , COALESCE(RSLT.SRVR_SE_CD, 'A0060002') AS SRVR_SE_CD /* 서버구분코드 */ , USCM.SF_COMM_CD_NM(COALESCE(RSLT.SRVR_SE_CD, 'A0060002')) AS SRVR_SE_NM /* 서버구분코드명 */ , (CASE WHEN RSLT.API_VER_SN IS NULL THEN () ELSE RSLT.API_VER_SN END) AS API_VER_SN /* API버전일련번호 */ , () AS PRDCT_LATEST_VER /* 상품최신버전 */ FROM USCM.TBCM_SAAS_PRDCT_M PRDCT LEFT OUTER JOIN USCM.TBCM_PRDCT_API_CMNCRSLT_L RSLT ON RSLT.SAAS_PRDCT_ID = PRDCT.SAAS_PRDCT_ID WHERE 1 = 1 AND PRDCT.USE_YN = 'Y' AND PRDCT.SAAS_PRDCT_ID = #{saasPrdctId}
AND RSLT.SRVR_SE_CD = #{srvrSeCd}
AND RSLT.API_VER_SN = #{apiVerSn}

SELECT /* ci.sc.cm.at.ApiTestMapper.select.selectApiArtclList - 상세 테스트 API 파라미터 목록 */ ARTCL.API_VER_SN /* API버전일련번호 */ , ARTCL.API_ID /* API 아이디 */ , ARTCL.API_ARTCL_SE_CD /* API항목 구분코드 */ , ARTCL.API_ARTCL_SN /* API항목 일련번호 */ , ARTCL.API_ARTCL_ATRB_NM /* API항목 속성명 */ , ARTCL.API_ARTCL_DATA_TYPE_CD /* API항목자료유형코드 */ , ARTCL.API_ARTCL_ESNTL_YN /* API항목 필수여부 */ , ARTCL.FRST_CRT_DT /* 최초생성일시 */ FROM USCM.TBCM_PRDCT_API_CMNCRSLT_L RSLT INNER JOIN USCM.TBCM_SAAS_PRDCT_M PRDCT ON RSLT.SAAS_PRDCT_ID = PRDCT.SAAS_PRDCT_ID INNER JOIN USCM.TBCM_STD_API_ARTCL_L ARTCL ON RSLT.API_ID = ARTCL.API_ID AND RSLT.API_VER_SN = ARTCL.API_VER_SN WHERE RSLT.SAAS_PRDCT_ID = #{saasPrdctId} AND PRDCT.USE_YN = 'Y' AND RSLT.SRVR_SE_CD = #{srvrSeCd} AND ARTCL.API_VER_SN = #{apiVerSn}
AND ARTCL.API_ARTCL_SE_CD IN ( 'B0030001', 'B0030002' )
AND ARTCL.API_ARTCL_SE_CD IN ( 'B0030003' )
AND ARTCL.API_ID = #{apiId}

mapper.delete:
DELETE  /* ci.sc.cm.at.ApiTestMapper.delete.deleteApiCommRslt - API 통신결과 삭제  */
FROM 	USCM.TBCM_PRDCT_API_CMNCRSLT_L
WHERE 	SAAS_PRDCT_ID = #{saasPrdctId}
AND 	SRVR_SE_CD = #{srvrSeCd}
AND 	API_ID = #{apiId}
AND 	API_VER_SN = #{apiVerSn}

mapper.insert:
INSERT /* ci.sc.cm.at.ApiTestMapper.insert.insertProdApiTest - API 통신결과 추가  */
INTO USCM.TBCM_PRDCT_API_CMNCRSLT_L (
	  SAAS_PRDCT_ID		/* 상품아이디 */
	, SRVR_SE_CD		/* 서버구분코드 */
	, API_ID			/* API 아이디 */
	, CMNC_RSLT_CD		/* 통신 결과 코드 */
	, CMNC_DT			/* 통신일시 */
	, CMNC_RSLT_CN		/* 통신결과내용 */
	, API_VER_SN		/* API버전일련번호 */
	, FRST_CRT_PRCR_ID	/* 최초생성처리자아이디 */
	, FRST_CRT_DT		/* 최초생성일시 */
	, LAST_CHG_PRCR_ID	/* 최종변경처리자아이디 */
	, LAST_CHG_DT		/* 최종변경일시 */
)
VALUES (
	  #{saasPrdctId}
	, #{srvrSeCd}
	, #{apiId}
	, #{cmncRsltCd}
	, #{cmncDt, jdbcType=TIMESTAMP}
	, #{cmncRsltCn}
	, #{apiVerSn}
	, #{frstCrtPrcrId}
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
	, #{frstCrtPrcrId}
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
)

mapper.select:
SELECT /* ci.sc.cm.at.ApiTestMapper.select.selectStdApiList - API 선택 팝업 */ API_VER_SN /* API버전일련번호 */ , API_ID /* API아이디 */ , API_NM /* API명 */ , SAAS_PRDCT_TYPE_CD /* SAAS제품유형코드 */ , USCM.SF_COMM_CD_NM(SAAS_PRDCT_TYPE_CD) SAAS_PRDCT_TYPE_NM /* SAAS제품유형코드명 */ , API_DMND_RSPNS_SE_CD /* API요청응답구분코드 */ , USCM.SF_COMM_CD_NM(API_DMND_RSPNS_SE_CD) AS API_DMND_RSPNS_SE_NM /* API요청응답구분코드명 */ , HTTP_CMNC_SE_CD /* HTTP통신구분코드 */ , USCM.SF_COMM_CD_NM(HTTP_CMNC_SE_CD) AS HTTP_CMNC_SE_NM /* HTTP통신구분코드명 */ , URI_ADDR /* URI주소 */ , FRST_CRT_PRCR_ID /* 최초생성처리자아이디 */ , FRST_CRT_DT /* 최초생성일시 */ , LAST_CHG_PRCR_ID /* 최종변경처리자아이디 */ , LAST_CHG_DT /* 최종변경일시 */ FROM USCM.TBCM_STD_API_M SA WHERE 1 = 1 AND SA.USE_YN = 'Y' AND SA.API_VER_SN = ( ) AND API_DMND_RSPNS_SE_CD = #{apiDmndRspnsSeCd}
AND API_NM LIKE '%' || #{apiNm} || '%'
AND SAAS_PRDCT_TYPE_CD = #{saasPrdctTypeCd}
AND HTTP_CMNC_SE_CD = #{httpCmncSeCd}
AND API_VER_SN = #{apiVerSn}
ORDER BY API_VER_SN DESC, API_NM
LIMIT #{pageSize} OFFSET (#{currentPage} - 1) * #{pageSize}

SELECT 	/* ci.sc.cm.at.ApiTestMapper.select.selectStdApiListTot - API 선택 팝업 수 */ 
	 	COUNT(1)
FROM 	USCM.TBCM_STD_API_M SA
WHERE 	1 = 1
AND 	SA.USE_YN = 'Y'
AND		SA.API_VER_SN = (  )
AND 	API_DMND_RSPNS_SE_CD = #{apiDmndRspnsSeCd}

	AND API_NM LIKE '%' || #{apiNm} || '%'


	AND SAAS_PRDCT_TYPE_CD = #{saasPrdctTypeCd}


	AND HTTP_CMNC_SE_CD = #{httpCmncSeCd}


	AND API_VER_SN = #{apiVerSn}

mapper.update:
UPDATE  /* ci.sc.cm.at.ApiTestMapper.update.updateProdApiTest - SaaS 상품 테스트 수정  */ 
		USCM.TBCM_PRDCT_API_CMNCRSLT_L		
   SET  LAST_CHG_PRCR_ID = #{lastChgPrcrId}							/* 최종변경처리자아이디 */
  	  , LAST_CHG_DT = TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')	/* 최종변경일시 */
  	  , CMNC_RSLT_CN = #{cmncRsltCn}								/* 통신결과내용 */
  	  , CMNC_DT = #{cmncDt, jdbcType=TIMESTAMP}
  	  , CMNC_RSLT_CD = #{cmncRsltCd}
 WHERE  SAAS_PRDCT_ID = #{saasPrdctId}
   AND  SRVR_SE_CD = #{srvrSeCd}
   AND  API_ID = #{apiId}
   AND 	API_VER_SN = #{apiVerSn}

mapper.delete:
DELETE  /* ci.sc.cm.at.ApiTestMapper.delete.deleteApiTestByOldVersion - 이전버전 api 테스트 삭제  */
FROM 	USCM.TBCM_PRDCT_API_CMNCRSLT_L
WHERE 	SAAS_PRDCT_ID = #{saasPrdctId}
AND 	API_VER_SN != #{apiVerSn}
AND 	EXISTS (SELECT 	1 
				FROM 	USCM.TBCM_PRDCT_API_CMNCRSLT_L 
				WHERE 	SAAS_PRDCT_ID = #{saasPrdctId}
				AND 	API_VER_SN = #{apiVerSn})

mapper.update:
UPDATE	/* ci.sc.cm.at.ApiTestMapper.update.updateApiCommScsYn - API 통신 성공여부 변경  */
		USCM.TBCM_CMNC_MNG_L
SET		  API_CMNC_SCS_YN = #{apiCmncScsYn}
		, LAST_CHG_DT = TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')

WHERE	SAAS_PRDCT_ID = #{saasPrdctId}
AND 	SRVR_SE_CD = #{srvrSeCd}
